@page "/book-appointment"
@rendermode InteractiveServer
@using sv_eaeb7d7c74584a66b02c0839588a5c52.Models
@using sv_eaeb7d7c74584a66b02c0839588a5c52.Services
@inject AppointmentService AppointmentSvc

<PageTitle>Book Appointment</PageTitle>

<h1>Book an Appointment</h1>

@if (submitted)
{
    <div class="alert alert-success mt-3">
        <h4>Appointment Booked!</h4>
        <p>
            <strong>@Model.PatientName</strong>, your appointment with
            <strong>@Model.Doctor</strong> on <strong>@Model.AppointmentDate?.ToString("MMMM d, yyyy")</strong>
            at <strong>@Model.TimeSlot</strong> has been confirmed.
        </p>
        <button class="btn btn-primary" @onclick="ResetForm">Book Another</button>
    </div>
}
else
{
    <EditForm EditContext="editContext" OnValidSubmit="HandleSubmit" FormName="book-appointment">
        <DataAnnotationsValidator />
        <CustomValidator @ref="customValidator" />

        @* ───── Step 1: Patient Information ───── *@
        <fieldset>
            <legend>Patient Information</legend>

            <div class="mb-3">
                <label class="form-label">Patient Name</label>
                <InputText class="form-control" @bind-Value="Model.PatientName" />
                <ValidationMessage For="() => Model.PatientName" />
            </div>

            <div class="mb-3">
                <label class="form-label">Email</label>
                <InputText class="form-control" @bind-Value="Model.Email" />
                <ValidationMessage For="() => Model.Email" />
            </div>

            <div class="mb-3">
                <label class="form-label">Phone</label>
                <InputText class="form-control" @bind-Value="Model.Phone" />
                <ValidationMessage For="() => Model.Phone" />
            </div>

            <div class="mb-3">
                <label class="form-label">Insurance Provider</label>
                <InputSelect class="form-select" @bind-Value="Model.InsuranceProvider">
                    <option value="">-- Select --</option>
                    <option value="Aetna">Aetna</option>
                    <option value="BlueCross">BlueCross</option>
                    <option value="Cigna">Cigna</option>
                    <option value="UnitedHealth">UnitedHealth</option>
                    <option value="None">None</option>
                </InputSelect>
                <ValidationMessage For="() => Model.InsuranceProvider" />
            </div>

            @if (!showStep2)
            {
                <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">
                    Next: Appointment Details
                </button>
            }
        </fieldset>

        @* ───── Step 2: Appointment Details ───── *@
        @if (showStep2)
        {
            <fieldset class="mt-4">
                <legend>Appointment Details</legend>

                <div class="mb-3">
                    <label class="form-label">Preferred Doctor</label>
                    <InputSelect class="form-select" @bind-Value="Model.Doctor" @bind:after="OnDoctorChanged">
                        <option value="">-- Select --</option>
                        @foreach (var doc in doctors)
                        {
                            <option value="@doc">@doc</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => Model.Doctor" />
                </div>

                <div class="mb-3">
                    <label class="form-label">Date</label>
                    <InputDate class="form-control" @bind-Value="Model.AppointmentDate" @bind:after="OnDateChanged" />
                    <ValidationMessage For="() => Model.AppointmentDate" />
                </div>

                <div class="mb-3">
                    <label class="form-label">Time Slot</label>
                    <InputSelect class="form-select" @bind-Value="Model.TimeSlot" disabled="@(!availableSlots.Any())">
                        <option value="">-- Select --</option>
                        @foreach (var slot in availableSlots)
                        {
                            <option value="@slot">@slot</option>
                        }
                    </InputSelect>
                    @if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue && !availableSlots.Any())
                    {
                        <div class="text-warning small">No slots available for this doctor/date.</div>
                    }
                    <ValidationMessage For="() => Model.TimeSlot" />
                </div>

                <div class="mb-3">
                    <label class="form-label">Reason for Visit</label>
                    <InputTextArea class="form-control" @bind-Value="Model.ReasonForVisit" rows="3" />
                    <ValidationMessage For="() => Model.ReasonForVisit" />
                    @if (Model.ReasonForVisit is not null)
                    {
                        <div class="form-text">@Model.ReasonForVisit.Length / 500 characters</div>
                    }
                </div>

                <div class="d-flex gap-2">
                    <button type="button" class="btn btn-outline-secondary" @onclick="BackToStep1">Back</button>
                    <button type="button" class="btn btn-info" disabled="@isChecking" @onclick="CheckAvailability">
                        @(isChecking ? "Checking..." : "Check Availability")
                    </button>
                    <button type="submit" class="btn btn-success" disabled="@(!availabilityChecked || isSubmitting)">
                        @(isSubmitting ? "Booking..." : "Book Appointment")
                    </button>
                </div>
            </fieldset>
        }
    </EditForm>
}

@code {
    private AppointmentModel Model = new();
    private EditContext? editContext;
    private CustomValidator? customValidator;

    private List<string> doctors = [];
    private List<string> availableSlots = [];

    private bool showStep2;
    private bool availabilityChecked;
    private bool isChecking;
    private bool isSubmitting;
    private bool submitted;

    protected override async Task OnInitializedAsync()
    {
        editContext = new EditContext(Model);
        doctors = await AppointmentSvc.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        // Validate only step-1 fields
        var isValid = true;
        var step1Fields = new[] {
            nameof(Model.PatientName),
            nameof(Model.Email),
            nameof(Model.Phone),
            nameof(Model.InsuranceProvider)
        };

        foreach (var field in step1Fields)
        {
            var fi = editContext!.Field(field);
            editContext.NotifyFieldChanged(fi);
            if (editContext.GetValidationMessages(fi).Any())
            {
                isValid = false;
            }
        }

        if (isValid)
        {
            showStep2 = true;
        }
    }

    private void BackToStep1()
    {
        showStep2 = false;
        availabilityChecked = false;
    }

    private async Task OnDoctorChanged()
    {
        availabilityChecked = false;
        Model.TimeSlot = null;
        await LoadSlots();
    }

    private async Task OnDateChanged()
    {
        availabilityChecked = false;
        Model.TimeSlot = null;
        await LoadSlots();
    }

    private async Task LoadSlots()
    {
        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue)
        {
            availableSlots = await AppointmentSvc.GetAvailableSlotsAsync(
                Model.Doctor, Model.AppointmentDate.Value);
        }
        else
        {
            availableSlots = [];
        }
    }

    private async Task CheckAvailability()
    {
        customValidator?.ClearErrors();
        availabilityChecked = false;

        // Validate step-2 required fields before calling the service
        var step2Valid = true;
        var step2Fields = new[] {
            nameof(Model.Doctor),
            nameof(Model.AppointmentDate),
            nameof(Model.TimeSlot),
            nameof(Model.ReasonForVisit)
        };
        foreach (var field in step2Fields)
        {
            var fi = editContext!.Field(field);
            editContext.NotifyFieldChanged(fi);
        }

        // Check data-annotation + IValidatableObject rules for step-2 fields
        if (string.IsNullOrWhiteSpace(Model.Doctor)
            || !Model.AppointmentDate.HasValue
            || string.IsNullOrWhiteSpace(Model.TimeSlot)
            || string.IsNullOrWhiteSpace(Model.ReasonForVisit))
        {
            editContext!.Validate();
            return;
        }

        if (Model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
        {
            editContext!.Validate();
            return;
        }

        isChecking = true;
        try
        {
            var errors = await AppointmentSvc.ValidatePatientAsync(
                Model.Email!,
                Model.InsuranceProvider!,
                Model.Doctor!,
                Model.TimeSlot!);

            if (errors.Count > 0)
            {
                // Map service field names to model property names
                var mapped = new Dictionary<string, List<string>>();
                foreach (var (key, msgs) in errors)
                {
                    var prop = key switch
                    {
                        "email" => nameof(Model.Email),
                        "doctor" => nameof(Model.Doctor),
                        "timeSlot" => nameof(Model.TimeSlot),
                        _ => key
                    };
                    mapped[prop] = msgs;
                }

                customValidator!.DisplayErrors(mapped);
                return;
            }

            availabilityChecked = true;
        }
        finally
        {
            isChecking = false;
        }
    }

    private async Task HandleSubmit()
    {
        if (!availabilityChecked)
        {
            return;
        }

        isSubmitting = true;
        try
        {
            await Task.Delay(500); // simulate booking
            submitted = true;
        }
        finally
        {
            isSubmitting = false;
        }
    }

    private void ResetForm()
    {
        Model = new();
        editContext = new EditContext(Model);
        showStep2 = false;
        availabilityChecked = false;
        submitted = false;
        availableSlots = [];
    }
}

