+
+        if (Model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
+        {
+            editContext!.Validate();
+            return;
+        }
+
+        isChecking = true;
+        try
+        {
+            var errors = await AppointmentSvc.ValidatePatientAsync(
+                Model.Email!,
+                Model.InsuranceProvider!,
+                Model.Doctor!,
+                Model.TimeSlot!);
+
+            if (errors.Count > 0)
+            {
+                // Map service field names to model property names
+                var mapped = new Dictionary<string, List<string>>();
+                foreach (var (key, msgs) in errors)
+                {
+                    var prop = key switch
+                    {
+                        "email" => nameof(Model.Email),
+                        "doctor" => nameof(Model.Doctor),
+                        "timeSlot" => nameof(Model.TimeSlot),
+                        _ => key
+                    };
+                    mapped[prop] = msgs;
+                }
+
+                customValidator!.DisplayErrors(mapped);
+                return;
+            }
+
+            availabilityChecked = true;
+        }
+        finally
+        {
+            isChecking = false;
+        }
+    }
+
+    private async Task HandleSubmit()
+    {
+        if (!availabilityChecked)
+        {
+            return;
+        }
+
+        isSubmitting = true;
+        try
+        {
+            await Task.Delay(500); // simulate booking
+            submitted = true;
+        }
+        finally
+        {
+            isSubmitting = false;
+        }
+    }
+
+    private void ResetForm()
+    {
+        Model = new();
+        editContext = new EditContext(Model);
+        showStep2 = false;
+        availabilityChecked = false;
+        submitted = false;
+        availableSlots = [];
+    }
+}
